/*
	VIOC_mission_b_client.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "mission_b_rules" (v2), parte del cliente: lo lanza init.sqf solo con interfaz (en la partida LAN tambien en el
	anfitrion). Marcadores LOCALES de la ofensiva insurgente para los jugadores del gobierno (Oeste):
	  - el servidor (VIOC_mission_b.sqf) publica VIOC_MB_MK = [version, [[id, [x, y], texto, color, tipo], ...]] con
	    publicVariable: el valor tambien llega a quien entra tarde (JIP), sin cola JIP de remoteExec;
	  - aqui, cada 3 s, si cambio la version (o el bando del jugador), se borran y se vuelven a crear los marcadores locales.
	    Un jugador del Este no ve nada. Sin frame a frame: un bucle con sleep 3.
*/
if (!hasInterface) exitWith {};
if (!isNil "VIOC_MBC_LOADED") exitWith {};
VIOC_MBC_LOADED = true;

[] spawn {
	waitUntil {sleep 1; !isNull player};
	private _mine = [];
	private _ver = -1;
	private _wasWest = false;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		private _side = missionNamespace getVariable ["CTI_P_SideJoined", playerSide];
		private _isWest = _side isEqualTo west;
		private _mk = missionNamespace getVariable ["VIOC_MB_MK", [0, []]];
		if !(_mk isEqualType [] && {count _mk > 1} && {(_mk select 1) isEqualType []}) then {_mk = [0, []]};
		if (!((_mk select 0) isEqualTo _ver) || {!(_isWest isEqualTo _wasWest)}) then {
			_ver = _mk select 0;
			_wasWest = _isWest;
			{ deleteMarkerLocal _x } forEach _mine;
			_mine = [];
			if (_isWest) then {
				{
					_x params [["_id", 0], ["_pos", [0, 0]], ["_txt", ""], ["_col", "ColorRed"], ["_type", "mil_warning"]];
					private _n = createMarkerLocal [format ["vioc_mb_mk_%1", _id], _pos];
					if (_n != "") then {
						_n setMarkerTypeLocal _type;
						_n setMarkerColorLocal _col;
						_n setMarkerTextLocal _txt;
						_mine pushBack _n;
					};
				} forEach (_mk select 1);
			};
		};
		sleep 3;
	};
	{ deleteMarkerLocal _x } forEach _mine;
};

