private _vioc_mbk = ((_town getVariable ["vioc_mb_key", false]) isEqualTo true) && {_sideID == CTI_WEST_ID} && {_upgrade < 1};
if (_vioc_mbk) then {_pool_group_size = _pool_group_size max (missionNamespace getVariable ["VIOC_MB_KEY_GROUP", 5])};
if (_sideID == CTI_WEST_ID && {((_town getVariable ["vioc_mb_key", false]) isEqualTo true) || {_upgrade >= 1}}) then {_town setVariable ["vioc_mb_made", time]}; //--- VIOC mission_b_rules: guarnicion del Oeste hecha (VIOC_mission_b.sqf no fuerza otra)
